-- Prepared bounded physical removal of disqualified trait rows, not a new engine admission.
DO $trait_purge$
DECLARE matched integer; removed bigint; observed_manifest text; observed_engines jsonb;
 before_manifest jsonb; current_manifest jsonb:='{}'::jsonb; manifest_row jsonb; surface record;
BEGIN
 PERFORM set_config('lock_timeout','3s',true);
 PERFORM set_config('statement_timeout','120s',true);
 LOCK TABLE public.civic_genome_trait,public.civic_genome_prism_verification_binding IN ACCESS EXCLUSIVE MODE;
 IF NOT EXISTS(SELECT 1 FROM pg_class WHERE oid='public.civic_genome_trait'::regclass AND relkind='r' AND pg_get_userbyid(relowner)='postgres' AND NOT relforcerowsecurity)
 OR EXISTS(SELECT 1 FROM pg_inherits WHERE inhrelid='public.civic_genome_trait'::regclass OR inhparent='public.civic_genome_trait'::regclass)
 OR EXISTS(SELECT 1 FROM pg_rewrite WHERE ev_class='public.civic_genome_trait'::regclass)
 THEN RAISE EXCEPTION 'trait table ownership, kind, inheritance or rules drift'; END IF;
 SELECT count(*) INTO matched FROM pg_constraint WHERE confrelid='public.civic_genome_trait'::regclass;
 IF matched<>1 OR NOT EXISTS(SELECT 1 FROM pg_constraint WHERE confrelid='public.civic_genome_trait'::regclass
  AND conrelid='public.civic_genome_prism_verification_binding'::regclass
  AND conname='civic_genome_prism_verification_binding_trait_id_fkey'
  AND confdeltype='a' AND convalidated
  AND pg_get_constraintdef(oid)='FOREIGN KEY (trait_id) REFERENCES civic_genome_trait(trait_id)')
 THEN RAISE EXCEPTION 'trait incoming dependency changed'; END IF;
 IF EXISTS(SELECT 1 FROM public.civic_genome_prism_verification_binding) THEN RAISE EXCEPTION 'trait bindings are not empty'; END IF;
 IF (SELECT count(*) FROM pg_trigger WHERE tgrelid='public.civic_genome_trait'::regclass AND NOT tgisinternal)<>1
 OR NOT EXISTS(SELECT 1 FROM pg_trigger WHERE tgrelid='public.civic_genome_trait'::regclass
  AND tgname='zz_civic_genome_block_rosetta_trait_write_v1' AND NOT tgisinternal AND tgenabled='O' AND tgtype=23
  AND md5(pg_get_functiondef(tgfoid))='87ffdb41a744456fb3863f2a0574b30c')
 OR EXISTS(SELECT 1 FROM pg_trigger WHERE tgrelid='public.civic_genome_trait'::regclass AND (tgtype & 8)<>0
  AND (NOT tgisinternal OR tgfoid<>'pg_catalog."RI_FKey_noaction_del"()'::regprocedure OR tgenabled<>'O'))
 THEN RAISE EXCEPTION 'trait write/delete trigger boundary changed'; END IF;
 IF NOT EXISTS(SELECT 1 FROM supabase_migrations.schema_migrations WHERE version='20261015135444'
 AND name='civic_genome_rosetta_sql_write_quarantine_v1' AND cardinality(statements)=1 AND md5(statements[1])='68ad3ca961b016b0a6a37c94f2861199') THEN RAISE EXCEPTION 'database write quarantine ledger differs'; END IF;
 WITH expected(table_name,trigger_name,body_md5,enabled) AS(VALUES ('civic_genome_trait','zz_civic_genome_block_rosetta_trait_write_v1','87ffdb41a744456fb3863f2a0574b30c','O'),('civic_genome_assembly_run','zz_civic_genome_block_rosetta_assembly_write_v1','87ffdb41a744456fb3863f2a0574b30c','O'),('civic_genome_rosetta_structural_representation','zz_civic_genome_block_rosetta_structural_representation_write_v','87ffdb41a744456fb3863f2a0574b30c','O'),('civic_genome_rosetta_source_binding','zz_civic_genome_block_rosetta_source_binding_write_v1','87ffdb41a744456fb3863f2a0574b30c','O'),('civic_genome_rosetta_generation_target','zz_civic_genome_block_rosetta_target_write_v1','87ffdb41a744456fb3863f2a0574b30c','O'),('civic_genome_bill','zz_civic_genome_block_bill_rosetta_payload_v1','ec8e3e387f823d806f926bd92585ec6e','O'),('civic_genome_bill_version','zz_civic_genome_block_bill_version_rosetta_receipt_v1','b29c9699c7831806f7ddcf346e309e22','O'),('civic_genome_projection_entity_version','zz_civic_genome_guard_source_only_history_v1','8c281d2d552148d50059c665e5f6aabf','O'),('civic_genome_rosetta_generation_activation_queue','zz_civic_genome_block_rosetta_activation_execution_v1','38c9a5480b91a640fe27776a7f0340bc','O'),('civic_genome_rosetta_generation_upgrade_queue','zz_civic_genome_block_rosetta_upgrade_execution_v1','38c9a5480b91a640fe27776a7f0340bc','O'))
 SELECT count(*) INTO matched FROM expected e JOIN pg_trigger t ON t.tgrelid=to_regclass(e.table_name) AND t.tgname=e.trigger_name WHERE NOT t.tgisinternal AND t.tgenabled::text=e.enabled AND md5(pg_get_functiondef(t.tgfoid))=e.body_md5;
 IF matched<>10 THEN RAISE EXCEPTION 'database write quarantine changed'; END IF;

 IF NOT EXISTS(SELECT 1 FROM supabase_migrations.schema_migrations WHERE version='20261017000912'
 AND name='retire_genome_legacy_structural_view_access_20261016' AND cardinality(statements)=1
 AND md5(statements[1])='0dcc197ff30adf74f88ed4d358f572dd') THEN RAISE EXCEPTION 'structural view retirement ledger differs'; END IF;
 SELECT count(*) INTO matched FROM (VALUES('public.docket_bill_drift_delta'),('public.docket_bill_impact_callouts'),('public.docket_bill_obligation_checklist'),('public.v_civic_genome_prism_verification_status'))v(name)
 JOIN pg_class c ON c.oid=to_regclass(v.name) WHERE c.relkind='v' AND pg_get_userbyid(c.relowner)='postgres'
 AND NOT EXISTS(SELECT 1 FROM aclexplode(c.relacl) a WHERE a.grantee<>c.relowner);
 IF matched<>4 THEN RAISE EXCEPTION 'structural view access reopened'; END IF;
 SELECT jsonb_agg(e ORDER BY engine_version) INTO observed_engines FROM
 (SELECT engine_version,count(*) AS row_count FROM public.civic_genome_trait GROUP BY engine_version)e;
 IF observed_engines IS DISTINCT FROM '[{"row_count":727,"engine_version":"rosetta-v3-deterministic-sql-1.0.0"},{"row_count":12,"engine_version":"rosetta-v3-deterministic-sql-2.0.0"},{"row_count":136,"engine_version":"rosetta-v3-deterministic-sql-2.1.0"},{"row_count":1626,"engine_version":"rosetta-v3-deterministic-sql-2.2.0"},{"row_count":50057,"engine_version":"rosetta-v3-deterministic-sql-2.3.0"},{"row_count":21300,"engine_version":"rosetta-v3-deterministic-sql-2.4.0"},{"row_count":919,"engine_version":"rosetta-v3-deterministic-sql-2.5.10"},{"row_count":21038,"engine_version":"rosetta-v3-deterministic-sql-2.5.11"},{"row_count":3344,"engine_version":"rosetta-v3-deterministic-sql-2.5.8"}]'::jsonb THEN RAISE EXCEPTION 'trait engine census differs'; END IF;
 SELECT encode(extensions.digest(convert_to(string_agg(encode(extensions.digest(convert_to(to_jsonb(t)::text,'UTF8'),'sha256'),'hex'),'' ORDER BY trait_id),'UTF8'),'sha256'),'hex') INTO observed_manifest FROM public.civic_genome_trait t;
 IF observed_manifest IS DISTINCT FROM '4c1ee67896649daee438bdc847da6dbef71f5eea37a2186d51f617ad6f170f0c'
 THEN RAISE EXCEPTION 'trait full-row manifest differs'; END IF;
 IF EXISTS(SELECT 1 FROM public.civic_genome_trait t
 LEFT JOIN public.civic_genome_bill b ON b.genome_bill_id=t.genome_bill_id
 LEFT JOIN public.docket_bill_detail_cache d ON d.bill_id=CASE WHEN b.structural_dna_json->>'source_bill_id'~'^[0-9]+$' THEN (b.structural_dna_json->>'source_bill_id')::integer ELSE NULL END
 WHERE b.genome_bill_id IS NULL OR d.bill_id IS NULL)
 THEN RAISE EXCEPTION 'trait bill or preserved Docket source missing'; END IF;
 -- Protected surfaces are SELECT-only. Concurrent source drift also fails closed;
 -- ordinary Docket source writes are not blocked by broad source-table locks.
 FOR surface IN SELECT * FROM (VALUES ('public.civic_genome_bill','genome_bill_id'),('public.civic_genome_bill_version','bill_version_id'),('public.civic_genome_family','family_id'),('public.docket_bill_detail_cache','bill_id'),('public.civic_genome_event','event_id'),('public.civic_genome_projection_entity_version','entity_version_id')) p(table_name,key_name) LOOP
 CASE surface.table_name
 WHEN 'public.civic_genome_bill' THEN EXECUTE 'SELECT jsonb_build_object(''count'',count(*),''sum_0'',sum(hashtextextended(ROW(t.genome_bill_id,t.family_id,t.bill_id,t.state_code,t.session_key,t.source_bill_number,t.source_bill_title,t.source_bill_url,t.bill_status,t.introduced_at,t.last_action_at,t.enacted_at,t.rosetta_extraction_run_id,t.structural_dna_hash,pg_column_size(t.structural_dna_json),pg_column_size(t.procedural_lifecycle_json),pg_column_size(t.jurisdiction_lineage_json),pg_column_size(t.constitutional_dependency_json),pg_column_size(t.fiscal_effects_json),pg_column_size(t.enforcement_graph_json),pg_column_size(t.downstream_impact_graph_json),t.current_state_position,t.created_at,t.updated_at,t.effective_at,t.last_observed_at,t.lifecycle_temporal_contract)::text,0)::numeric)::text,''sum_1'',sum(hashtextextended(ROW(t.genome_bill_id,t.family_id,t.bill_id,t.state_code,t.session_key,t.source_bill_number,t.source_bill_title,t.source_bill_url,t.bill_status,t.introduced_at,t.last_action_at,t.enacted_at,t.rosetta_extraction_run_id,t.structural_dna_hash,pg_column_size(t.structural_dna_json),pg_column_size(t.procedural_lifecycle_json),pg_column_size(t.jurisdiction_lineage_json),pg_column_size(t.constitutional_dependency_json),pg_column_size(t.fiscal_effects_json),pg_column_size(t.enforcement_graph_json),pg_column_size(t.downstream_impact_graph_json),t.current_state_position,t.created_at,t.updated_at,t.effective_at,t.last_observed_at,t.lifecycle_temporal_contract)::text,1)::numeric)::text) FROM public.civic_genome_bill t' INTO manifest_row;
WHEN 'public.civic_genome_bill_version' THEN EXECUTE 'SELECT jsonb_build_object(''count'',count(*),''sum_0'',sum(hashtextextended(ROW(t.bill_version_id,t.genome_bill_id,t.source_document_key,t.source_bill_id,t.document_family,t.version_type,t.provider_sequence,t.stage_rank,t.chamber,t.predecessor_bill_version_id,t.base_bill_version_id,t.version_fingerprint,t.rosetta_source_document_id,t.rosetta_extraction_run_id,t.assembly_run_id,t.prism_verification_run_id,t.processing_state,t.failure_code,pg_column_size(t.receipt_json),t.created_at,t.updated_at)::text,0)::numeric)::text,''sum_1'',sum(hashtextextended(ROW(t.bill_version_id,t.genome_bill_id,t.source_document_key,t.source_bill_id,t.document_family,t.version_type,t.provider_sequence,t.stage_rank,t.chamber,t.predecessor_bill_version_id,t.base_bill_version_id,t.version_fingerprint,t.rosetta_source_document_id,t.rosetta_extraction_run_id,t.assembly_run_id,t.prism_verification_run_id,t.processing_state,t.failure_code,pg_column_size(t.receipt_json),t.created_at,t.updated_at)::text,1)::numeric)::text) FROM public.civic_genome_bill_version t' INTO manifest_row;
WHEN 'public.civic_genome_family' THEN EXECUTE 'SELECT jsonb_build_object(''count'',count(*),''sum_0'',sum(hashtextextended(ROW(t.family_id,t.family_key,t.family_label,t.policy_domain,t.family_status,t.first_seen_at,t.last_seen_at,t.first_enacted_at,t.last_event_at,t.active_state_count,t.introduced_state_count,t.enacted_state_count,t.failed_state_count,t.momentum_score,t.acceleration_score,t.collapse_score,pg_column_size(t.signature_json),t.created_at,t.updated_at)::text,0)::numeric)::text,''sum_1'',sum(hashtextextended(ROW(t.family_id,t.family_key,t.family_label,t.policy_domain,t.family_status,t.first_seen_at,t.last_seen_at,t.first_enacted_at,t.last_event_at,t.active_state_count,t.introduced_state_count,t.enacted_state_count,t.failed_state_count,t.momentum_score,t.acceleration_score,t.collapse_score,pg_column_size(t.signature_json),t.created_at,t.updated_at)::text,1)::numeric)::text) FROM public.civic_genome_family t' INTO manifest_row;
WHEN 'public.docket_bill_detail_cache' THEN EXECUTE 'SELECT jsonb_build_object(''count'',count(*),''sum_0'',sum(hashtextextended(ROW(t.bill_id,pg_column_size(t.bill),t.fetched_at,t.source,t.created_at,t.updated_at)::text,0)::numeric)::text,''sum_1'',sum(hashtextextended(ROW(t.bill_id,pg_column_size(t.bill),t.fetched_at,t.source,t.created_at,t.updated_at)::text,1)::numeric)::text) FROM public.docket_bill_detail_cache t' INTO manifest_row;
WHEN 'public.civic_genome_event' THEN EXECUTE 'SELECT jsonb_build_object(''count'',count(*),''sum_0'',sum(hashtextextended(ROW(t.event_id,t.family_id,t.genome_bill_id,t.bill_id,t.state_code,t.event_type,t.event_timestamp,t.prior_status,t.next_status,t.amendment_version,pg_column_size(t.source_trace),pg_column_size(t.event_payload_json),t.created_at)::text,0)::numeric)::text,''sum_1'',sum(hashtextextended(ROW(t.event_id,t.family_id,t.genome_bill_id,t.bill_id,t.state_code,t.event_type,t.event_timestamp,t.prior_status,t.next_status,t.amendment_version,pg_column_size(t.source_trace),pg_column_size(t.event_payload_json),t.created_at)::text,1)::numeric)::text) FROM public.civic_genome_event t' INTO manifest_row;
WHEN 'public.civic_genome_projection_entity_version' THEN EXECUTE 'SELECT jsonb_build_object(''count'',count(*),''sum_0'',sum(hashtextextended(ROW(t.entity_version_id,t.entity_type,t.entity_id,t.family_id,t.observed_at,t.record_hash,t.created_at)::text,0)::numeric)::text,''sum_1'',sum(hashtextextended(ROW(t.entity_version_id,t.entity_type,t.entity_id,t.family_id,t.observed_at,t.record_hash,t.created_at)::text,1)::numeric)::text) FROM public.civic_genome_projection_entity_version t' INTO manifest_row;
 ELSE RAISE EXCEPTION 'unknown protection surface'; END CASE;
 current_manifest:=current_manifest||jsonb_build_object(surface.table_name,manifest_row);
END LOOP;
 before_manifest:=current_manifest;
 DELETE FROM public.civic_genome_trait WHERE engine_version=ANY(ARRAY['rosetta-v3-deterministic-sql-1.0.0','rosetta-v3-deterministic-sql-2.0.0','rosetta-v3-deterministic-sql-2.1.0','rosetta-v3-deterministic-sql-2.2.0','rosetta-v3-deterministic-sql-2.3.0','rosetta-v3-deterministic-sql-2.4.0','rosetta-v3-deterministic-sql-2.5.10','rosetta-v3-deterministic-sql-2.5.11','rosetta-v3-deterministic-sql-2.5.8']);
 GET DIAGNOSTICS removed=ROW_COUNT;
 IF removed<>99159 OR EXISTS(SELECT 1 FROM public.civic_genome_trait) THEN RAISE EXCEPTION 'trait removal count differs'; END IF;
 REVOKE SELECT ON TABLE public.civic_genome_trait FROM PUBLIC,anon,authenticated,service_role;
 IF EXISTS(SELECT 1 FROM (VALUES('anon'),('authenticated'),('service_role'))r(name) WHERE has_table_privilege(r.name,'public.civic_genome_trait','SELECT'))
 THEN RAISE EXCEPTION 'retired trait application read remains'; END IF;
 current_manifest:='{}'::jsonb;
 FOR surface IN SELECT * FROM (VALUES ('public.civic_genome_bill','genome_bill_id'),('public.civic_genome_bill_version','bill_version_id'),('public.civic_genome_family','family_id'),('public.docket_bill_detail_cache','bill_id'),('public.civic_genome_event','event_id'),('public.civic_genome_projection_entity_version','entity_version_id')) p(table_name,key_name) LOOP
 CASE surface.table_name
 WHEN 'public.civic_genome_bill' THEN EXECUTE 'SELECT jsonb_build_object(''count'',count(*),''sum_0'',sum(hashtextextended(ROW(t.genome_bill_id,t.family_id,t.bill_id,t.state_code,t.session_key,t.source_bill_number,t.source_bill_title,t.source_bill_url,t.bill_status,t.introduced_at,t.last_action_at,t.enacted_at,t.rosetta_extraction_run_id,t.structural_dna_hash,pg_column_size(t.structural_dna_json),pg_column_size(t.procedural_lifecycle_json),pg_column_size(t.jurisdiction_lineage_json),pg_column_size(t.constitutional_dependency_json),pg_column_size(t.fiscal_effects_json),pg_column_size(t.enforcement_graph_json),pg_column_size(t.downstream_impact_graph_json),t.current_state_position,t.created_at,t.updated_at,t.effective_at,t.last_observed_at,t.lifecycle_temporal_contract)::text,0)::numeric)::text,''sum_1'',sum(hashtextextended(ROW(t.genome_bill_id,t.family_id,t.bill_id,t.state_code,t.session_key,t.source_bill_number,t.source_bill_title,t.source_bill_url,t.bill_status,t.introduced_at,t.last_action_at,t.enacted_at,t.rosetta_extraction_run_id,t.structural_dna_hash,pg_column_size(t.structural_dna_json),pg_column_size(t.procedural_lifecycle_json),pg_column_size(t.jurisdiction_lineage_json),pg_column_size(t.constitutional_dependency_json),pg_column_size(t.fiscal_effects_json),pg_column_size(t.enforcement_graph_json),pg_column_size(t.downstream_impact_graph_json),t.current_state_position,t.created_at,t.updated_at,t.effective_at,t.last_observed_at,t.lifecycle_temporal_contract)::text,1)::numeric)::text) FROM public.civic_genome_bill t' INTO manifest_row;
WHEN 'public.civic_genome_bill_version' THEN EXECUTE 'SELECT jsonb_build_object(''count'',count(*),''sum_0'',sum(hashtextextended(ROW(t.bill_version_id,t.genome_bill_id,t.source_document_key,t.source_bill_id,t.document_family,t.version_type,t.provider_sequence,t.stage_rank,t.chamber,t.predecessor_bill_version_id,t.base_bill_version_id,t.version_fingerprint,t.rosetta_source_document_id,t.rosetta_extraction_run_id,t.assembly_run_id,t.prism_verification_run_id,t.processing_state,t.failure_code,pg_column_size(t.receipt_json),t.created_at,t.updated_at)::text,0)::numeric)::text,''sum_1'',sum(hashtextextended(ROW(t.bill_version_id,t.genome_bill_id,t.source_document_key,t.source_bill_id,t.document_family,t.version_type,t.provider_sequence,t.stage_rank,t.chamber,t.predecessor_bill_version_id,t.base_bill_version_id,t.version_fingerprint,t.rosetta_source_document_id,t.rosetta_extraction_run_id,t.assembly_run_id,t.prism_verification_run_id,t.processing_state,t.failure_code,pg_column_size(t.receipt_json),t.created_at,t.updated_at)::text,1)::numeric)::text) FROM public.civic_genome_bill_version t' INTO manifest_row;
WHEN 'public.civic_genome_family' THEN EXECUTE 'SELECT jsonb_build_object(''count'',count(*),''sum_0'',sum(hashtextextended(ROW(t.family_id,t.family_key,t.family_label,t.policy_domain,t.family_status,t.first_seen_at,t.last_seen_at,t.first_enacted_at,t.last_event_at,t.active_state_count,t.introduced_state_count,t.enacted_state_count,t.failed_state_count,t.momentum_score,t.acceleration_score,t.collapse_score,pg_column_size(t.signature_json),t.created_at,t.updated_at)::text,0)::numeric)::text,''sum_1'',sum(hashtextextended(ROW(t.family_id,t.family_key,t.family_label,t.policy_domain,t.family_status,t.first_seen_at,t.last_seen_at,t.first_enacted_at,t.last_event_at,t.active_state_count,t.introduced_state_count,t.enacted_state_count,t.failed_state_count,t.momentum_score,t.acceleration_score,t.collapse_score,pg_column_size(t.signature_json),t.created_at,t.updated_at)::text,1)::numeric)::text) FROM public.civic_genome_family t' INTO manifest_row;
WHEN 'public.docket_bill_detail_cache' THEN EXECUTE 'SELECT jsonb_build_object(''count'',count(*),''sum_0'',sum(hashtextextended(ROW(t.bill_id,pg_column_size(t.bill),t.fetched_at,t.source,t.created_at,t.updated_at)::text,0)::numeric)::text,''sum_1'',sum(hashtextextended(ROW(t.bill_id,pg_column_size(t.bill),t.fetched_at,t.source,t.created_at,t.updated_at)::text,1)::numeric)::text) FROM public.docket_bill_detail_cache t' INTO manifest_row;
WHEN 'public.civic_genome_event' THEN EXECUTE 'SELECT jsonb_build_object(''count'',count(*),''sum_0'',sum(hashtextextended(ROW(t.event_id,t.family_id,t.genome_bill_id,t.bill_id,t.state_code,t.event_type,t.event_timestamp,t.prior_status,t.next_status,t.amendment_version,pg_column_size(t.source_trace),pg_column_size(t.event_payload_json),t.created_at)::text,0)::numeric)::text,''sum_1'',sum(hashtextextended(ROW(t.event_id,t.family_id,t.genome_bill_id,t.bill_id,t.state_code,t.event_type,t.event_timestamp,t.prior_status,t.next_status,t.amendment_version,pg_column_size(t.source_trace),pg_column_size(t.event_payload_json),t.created_at)::text,1)::numeric)::text) FROM public.civic_genome_event t' INTO manifest_row;
WHEN 'public.civic_genome_projection_entity_version' THEN EXECUTE 'SELECT jsonb_build_object(''count'',count(*),''sum_0'',sum(hashtextextended(ROW(t.entity_version_id,t.entity_type,t.entity_id,t.family_id,t.observed_at,t.record_hash,t.created_at)::text,0)::numeric)::text,''sum_1'',sum(hashtextextended(ROW(t.entity_version_id,t.entity_type,t.entity_id,t.family_id,t.observed_at,t.record_hash,t.created_at)::text,1)::numeric)::text) FROM public.civic_genome_projection_entity_version t' INTO manifest_row;
 ELSE RAISE EXCEPTION 'unknown protection surface'; END CASE;
 current_manifest:=current_manifest||jsonb_build_object(surface.table_name,manifest_row);
END LOOP;
 IF current_manifest IS DISTINCT FROM before_manifest THEN RAISE EXCEPTION 'source identity event or sealed-history conservation failed'; END IF;
 IF NOT EXISTS(SELECT 1 FROM supabase_migrations.schema_migrations WHERE version='20261015135444'
 AND name='civic_genome_rosetta_sql_write_quarantine_v1' AND cardinality(statements)=1 AND md5(statements[1])='68ad3ca961b016b0a6a37c94f2861199') THEN RAISE EXCEPTION 'database write quarantine ledger differs'; END IF;
 WITH expected(table_name,trigger_name,body_md5,enabled) AS(VALUES ('civic_genome_trait','zz_civic_genome_block_rosetta_trait_write_v1','87ffdb41a744456fb3863f2a0574b30c','O'),('civic_genome_assembly_run','zz_civic_genome_block_rosetta_assembly_write_v1','87ffdb41a744456fb3863f2a0574b30c','O'),('civic_genome_rosetta_structural_representation','zz_civic_genome_block_rosetta_structural_representation_write_v','87ffdb41a744456fb3863f2a0574b30c','O'),('civic_genome_rosetta_source_binding','zz_civic_genome_block_rosetta_source_binding_write_v1','87ffdb41a744456fb3863f2a0574b30c','O'),('civic_genome_rosetta_generation_target','zz_civic_genome_block_rosetta_target_write_v1','87ffdb41a744456fb3863f2a0574b30c','O'),('civic_genome_bill','zz_civic_genome_block_bill_rosetta_payload_v1','ec8e3e387f823d806f926bd92585ec6e','O'),('civic_genome_bill_version','zz_civic_genome_block_bill_version_rosetta_receipt_v1','b29c9699c7831806f7ddcf346e309e22','O'),('civic_genome_projection_entity_version','zz_civic_genome_guard_source_only_history_v1','8c281d2d552148d50059c665e5f6aabf','O'),('civic_genome_rosetta_generation_activation_queue','zz_civic_genome_block_rosetta_activation_execution_v1','38c9a5480b91a640fe27776a7f0340bc','O'),('civic_genome_rosetta_generation_upgrade_queue','zz_civic_genome_block_rosetta_upgrade_execution_v1','38c9a5480b91a640fe27776a7f0340bc','O'))
 SELECT count(*) INTO matched FROM expected e JOIN pg_trigger t ON t.tgrelid=to_regclass(e.table_name) AND t.tgname=e.trigger_name WHERE NOT t.tgisinternal AND t.tgenabled::text=e.enabled AND md5(pg_get_functiondef(t.tgfoid))=e.body_md5;
 IF matched<>10 THEN RAISE EXCEPTION 'database write quarantine changed'; END IF;

